{"summary": "Update Region Configuration Settings", "description": "Modify the configuration settings for a specific region in the monitored network.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"region": {"type": "string", "description": "The region ID for which the configuration settings are being updated."}, "new_config_params": {"type": "object", "description": "New configuration parameters for the region.", "additionalProperties": true}}, "required": ["region", "new_config_params"]}}}}, "responses": {"200": {"description": "Region configuration updated successfully."}, "400": {"description": "Invalid input parameters."}}}

Endpoint: GET /energy-output/history
Specification:
{"summary": "Access Historical Energy Output Records", "description": "Retrieve historical energy output data for all devices or a specific device, segmented by date or time period.", "parameters": [{"name": "device_id", "in": "query", "description": "Optional. Specify the device ID to filter historical data.", "required": false, "schema": {"type": "string"}}, {"name": "start_date", "in": "query", "description": "The start date for historical records in ISO 8601 format (e.g., 2023-01-01).", "required": true, "schema": {"type": "string", "format": "date"}}, {"name": "end_date", "in": "query", "description": "The end date for historical records in ISO 8601 format (e.g., 2023-01-31).", "required": true, "schema": {"type": "string", "format": "date"}}], "responses": {"200": {"description": "Energy output data retrieved successfully.", "content": {"application/json": {"example": {"data": [{"date": "2023-01-01", "output_kw": 120.5}]}}}}}}

Endpoint: GET /analysis/overview
Specification:
{"summary": "Energy Usage Overview", "description": "Retrieve a summary snapshot of energy usage patterns across all clients.", "responses": {"200": {"description": "Overview successfully retrieved.", "content": {"application/json": {"schema": {"type": "object", "properties": {"total_clients": {"type": "integer", "description": "Total number of clients being analyzed."}, "average_consumption": {"type": "number", "format": "float", "description": "Average energy consumption across all clients in kWh."}, "peak_consumption_times": {"type": "array", "items": {"type": "string", "format": "date-time", "description": "Time periods of peak energy consumption."}, "description": "Array of peak energy consumption times."}}}}}}}}

Endpoint: GET /properties/valuation
Specification:
{"summary": "Retrieve the estimated value of a property", "description": "This endpoint allows users to obtain an estimated market value for a property by providing its location and key features (e.g., size, number of bedrooms, etc.). The estimation leverages historical data, market trends, and comparable properties.", "parameters": [{"name": "location", "in": "query", "required": true, "description": "The location of the property (e.g., city, state, or specific address).", "schema": {"type": "string"}}, {"name": "bedrooms", "in": "query", "required": false, "description": "The number of bedrooms in the property.", "schema": {"type": "integer", "example": 3}}, {"name": "bathrooms", "in": "query", "required": false, "description": "The number of bathrooms in the property.", "schema": {"type": "integer", "example": 2}}, {"name": "square_feet", "in": "query", "required": false, "description": "The total area of the property in square feet.", "schema": {"type": "integer", "example": 1500}}], "responses": {"200": {"description": "Successful response with the estimated value of the property.", "content": {"application/json": {"schema": {"type": "object", "properties": {"estimated_value": {"type": "number", "description": "The estimated market value of the property in USD."}, "confidence_score": {"type": "number", "format": "float", "description": "A confidence score (0-100) indicating the reliability of the valuation."}}}}}}}}

Endpoint: GET /payments/outstanding/{tenantId}
Specification:
{"summary": "Check outstanding payments", "description": "Retrieve the list of outstanding payments for a specific tenant ID.", "parameters": [{"name": "tenantId", "in": "path", "required": true, "schema": {"type": "string"}, "description": "Unique identifier for the tenant."}], "responses": {"200": {"description": "Outstanding payments retrieved successfully.", "content": {"application/json": {"schema": {"type": "array", "items": {"type": "object", "properties": {"invoiceId": {"type": "string", "description": "Unique identifier for the payment invoice."}, "amount": {"type": "number", "description": "Outstanding payment amount."}, "dueDate": {"type": "string", "format": "date", "description": "Due date for the payment."}}}}}}}, "404": {"description": "Tenant not found."}}}

Endpoint: GET /property-value-estimate
Specification:
{"summary": "Fetch Property Value Estimate", "description": "Fetch an estimated value of a property based on its location and other provided details.", "parameters": [{"name": "location", "in": "query", "required": true, "description": "The location of the property (e.g., address, city, state).", "schema": {"type": "string"}}, {"name": "propertyDetails", "in": "query", "required": false, "description": "Additional details about the property (e.g., size, type).", "schema": {"type": "string"}}], "responses": {"200": {"description": "Property value estimate retrieved successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"estimatedValue": {"type": "number", "description": "The estimated value of the property in USD."}}}}}}}}

Endpoint: GET /reviews/{agentId}
Specification:
{"summary": "Retrieve Reviews for an Agent", "description": "Retrieve all reviews and ratings for a specific real estate agent.", "parameters": [{"name": "agentId", "in": "path", "description": "The ID of the agent whose reviews are requested.", "required": true, "schema": {"type": "string"}}], "responses": {"200": {"description": "List of reviews for the specified agent.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/Review"}}}}}}}

Endpoint: GET /properties
Specification:
{"summary": "Retrieve properties matching filters", "description": "Fetch a list of properties available for sale or rent. The results can be filtered based on location, price range, amenities, and other optional parameters.", "parameters": [{"name": "location", "in": "query", "description": "Filter properties by location (e.g., city, neighborhood, or address).", "required": false, "schema": {"type": "string"}}, {"name": "min_price", "in": "query", "description": "Filter properties by minimum price range.", "required": false, "schema": {"type": "number"}}, {"name": "max_price", "in": "query", "description": "Filter properties by maximum price range.", "required": false, "schema": {"type": "number"}}, {"name": "amenities", "in": "query", "description": "Filter properties by required amenities (e.g., parking, pool, garden).", "required": false, "schema": {"type": "string"}}, {"name": "property_type", "in": "query", "description": "Filter properties by type (e.g., apartment, house, commercial).", "required": false, "schema": {"type": "string"}}], "responses": {"200": {"description": "A list of properties matching the specified filters.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/Property"}}}}}}}

Endpoint: GET /properties/comparison
Specification:
{"summary": "Compare properties", "description": "Provide a detailed comparison of two or more properties based on their attributes.", "parameters": [{"name": "property_ids", "in": "query", "required": true, "description": "A comma-separated list of property IDs to compare.", "schema": {"type": "string"}}], "responses": {"200": {"description": "Successfully retrieved property comparison results.", "content": {"application/json": {"schema": {"type": "array", "items": {"type": "object", "properties": {"property_id": {"type": "string"}, "details": {"type": "object", "properties": {"bedrooms": {"type": "integer"}, "bathrooms": {"type": "integer"}, "square_feet": {"type": "integer"}}}}}}}}}}}

Endpoint: GET /recommendations
Specification:
{"summary": "Get Recommended Agents", "description": "Retrieve recommended agents for a specific property based on user preferences and performance metrics.", "parameters": [{"name": "propertyId", "in": "query", "description": "ID of the property for which recommendations are requested.", "required": true, "schema": {"type": "string"}}], "responses": {"200": {"description": "List of recommended agents.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/Agent"}}}}}}}

Endpoint: POST /properties/add
Specification:
{"summary": "Submit property details for storage and analysis", "description": "This endpoint allows users to add detailed information about a property to the service's database for future analysis and retrieval.", "requestBody": {"description": "The property information to be submitted.", "required": true, "content": {"application/json": {"schema": {"type": "object", "required": ["location", "features"], "properties": {"location": {"type": "string", "description": "The property's location (e.g., city, state, or address)."}, "features": {"type": "object", "description": "Details about the features of the property (e.g., number of bedrooms, area, etc.).", "properties": {"bedrooms": {"type": "integer"}, "bathrooms": {"type": "integer"}, "square_feet": {"type": "integer"}}}}}}}}, "responses": {"201": {"description": "The property was successfully added.", "content": {"application/json": {"schema": {"type": "object", "properties": {"message": {"type": "string"}}}}}}}}

Endpoint: GET /properties/similar
Specification:
{"summary": "Retrieve similar properties", "description": "Fetch a list of properties similar to a given property based on its features and location.", "parameters": [{"name": "property_id", "in": "query", "required": true, "description": "The unique identifier of the property to find similar properties for.", "schema": {"type": "string"}}], "responses": {"200": {"description": "Successfully retrieved similar properties.", "content": {"application/json": {"schema": {"type": "array", "items": {"type": "object", "properties": {"property_id": {"type": "string"}, "location": {"type": "string"}, "features": {"type": "object", "properties": {"bedrooms": {"type": "integer"}, "bathrooms": {"type": "integer"}, "square_feet": {"type": "integer"}}}}}}}}}}}

Endpoint: POST /evaluate-affordability
Specification:
{"summary": "Evaluate Affordability", "description": "Analyze user's financial data to assess their property affordability.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"income": {"type": "number", "description": "User's annual income in USD."}, "expenses": {"type": "number", "description": "User's monthly expenses in USD."}, "downPayment": {"type": "number", "description": "Proposed down payment amount in USD."}}, "required": ["income", "expenses", "downPayment"]}}}}, "responses": {"200": {"description": "Affordability analysis completed successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"affordablePrice": {"type": "number", "description": "The maximum affordable property price based on provided data."}}}}}}}}
